export const batch_affine_finalize_collect = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}

// Pass A of the two-pass batch-affine finalize.
//
// Resolves the j=0 (p1) and j=1 (p2) sides for each bucket index \`bi\`,
// determines the case, and either:
//   - Writes the bucket directly (cases 1-3: identity / one side only),
//     storing R (Montgomery 1) as a placeholder in pair_delta[id] so the
//     downstream batch_inverse treats this slot as a no-op.
//   - Computes delta = p2.x - p1.x and writes to pair_delta[id]
//     (case 4: both active), leaving the bucket untouched. The
//     downstream Pass B reads inv_delta[id] and finishes the affine add.
//
// The previous monolithic finalize kernel called \`fr_inv\` per thread
// (~520 montgomery_products) — at T*h ≈ 524k threads the pass cost ~150 ms
// of GPU time. Splitting into collect → batch_inverse → apply trades
// the per-thread fr_inv for one shared inversion, dropping the cost to
// ~30 ms.
//
// \`R\` placeholder rationale: writing R for non-case-4 slots makes the
// batch_inverse prefix product cleanly include them as identity multiplies
// (R * x = x in Montgomery form). The Pass B re-resolves the case and
// only consumes inv_delta when bot sides are active, so the placeholder
// inverse value is never used.

@group(0) @binding(0)
var<storage, read> running_x: array<BigInt>;
@group(0) @binding(1)
var<storage, read> running_y: array<BigInt>;
@group(0) @binding(2)
var<storage, read> bucket_active: array<u32>;

@group(0) @binding(3)
var<storage, read_write> bucket_x: array<BigInt>;
@group(0) @binding(4)
var<storage, read_write> bucket_y: array<BigInt>;
@group(0) @binding(5)
var<storage, read_write> bucket_z: array<BigInt>;

@group(0) @binding(6)
var<storage, read_write> pair_delta: array<BigInt>;

@group(0) @binding(7)
var<uniform> params: vec4<u32>;
// params[0] = num_y_workgroups
// params[1] = num_z_workgroups
// params[2] = subtask_offset
// params[3] = workspace_stride

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

// Field negation in canonical form: returns (p - y) mod p. fr_sub
// outputs guarantee 0 <= y < p so this is safe.
fn neg_y(running_idx: u32) -> BigInt {
    var p_mod = get_p();
    var y = running_y[running_idx];
    var ny: BigInt;
    let _b = bigint_sub(&p_mod, &y, &ny);
    return ny;
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let num_y_workgroups = params[0];
    let num_z_workgroups = params[1];
    let subtask_offset = params[2];
    let workspace_stride = params[3];

    let gidx = global_id.x;
    let gidy = global_id.y;
    var gidz = global_id.z;
    let id = (gidx * num_y_workgroups + gidy) * num_z_workgroups + gidz;

    let num_columns = {{ num_columns }}u;
    let h = {{ half_num_columns }}u;

    let subtask_idx = id / h;
    let bi = id + subtask_offset * h;
    let workspace_offset = (subtask_idx + subtask_offset) * workspace_stride;

    // ---- Resolve j = 0 side as affine (X1, Y1) + active flag ----
    var p1_x: BigInt;
    var p1_y: BigInt;
    var p1_active: bool = false;
    {
        var row_idx = (id % h) + h;
        if (id % h == 0u) {
            row_idx = 0u;
        }

        var bucket_idx: u32 = 0u;
        var negate: bool = false;
        if (h > row_idx) {
            bucket_idx = h - row_idx;
            negate = true;
        } else {
            bucket_idx = row_idx - h;
        }

        if (bucket_idx > 0u) {
            let workspace_idx = workspace_offset + row_idx;
            if (bucket_active[workspace_idx] != 0u) {
                p1_x = running_x[workspace_idx];
                if (negate) {
                    p1_y = neg_y(workspace_idx);
                } else {
                    p1_y = running_y[workspace_idx];
                }
                p1_active = true;
            }
        }
    }

    // ---- Resolve j = 1 side as affine (X2, Y2) + active flag ----
    var p2_x: BigInt;
    var p2_y: BigInt;
    var p2_active: bool = false;
    {
        let row_idx = h - (id % h);
        var bucket_idx: u32 = 0u;
        var negate: bool = false;
        if (h > row_idx) {
            bucket_idx = h - row_idx;
            negate = true;
        } else {
            bucket_idx = row_idx - h;
        }

        if (bucket_idx > 0u) {
            let workspace_idx = workspace_offset + row_idx;
            if (bucket_active[workspace_idx] != 0u) {
                p2_x = running_x[workspace_idx];
                if (negate) {
                    p2_y = neg_y(workspace_idx);
                } else {
                    p2_y = running_y[workspace_idx];
                }
                p2_active = true;
            }
        }
    }

    // ---- Cases ----
    if (!p1_active && !p2_active) {
        var zero: BigInt;
        bucket_x[bi] = zero;
        bucket_y[bi] = get_r();
        bucket_z[bi] = zero;
        pair_delta[id] = get_r(); // placeholder — never consumed.
        return;
    }

    if (!p2_active) {
        bucket_x[bi] = p1_x;
        bucket_y[bi] = p1_y;
        bucket_z[bi] = get_r();
        pair_delta[id] = get_r();
        return;
    }

    if (!p1_active) {
        bucket_x[bi] = p2_x;
        bucket_y[bi] = p2_y;
        bucket_z[bi] = get_r();
        pair_delta[id] = get_r();
        return;
    }

    // Both active: emit delta. Bucket left untouched (Pass B will write).
    var delta = fr_sub(&p2_x, &p1_x);
    pair_delta[id] = delta;

    {{{ recompile }}}
}
`;

export const batch_affine_init = `{{> structs }}

// Init kernel for the batch-affine SMVP pipeline.
// NOTE: this kernel uses only u32 / BigInt-struct copy operations and
// does not call any function from \`bigint_funcs\`, \`field_funcs\`, or
// \`montgomery_product_funcs\`. We therefore omit those partials so the
// kernel doesn't drag in references to NUM_WORDS / WORD_SIZE / MASK
// constants (which are defined in \`montgomery_product_funcs\` and are
// not needed here).
//
// Dispatched ONCE per MSM, covering all T * num_columns buckets across
// all subtasks. One thread per (subtask, bucket_local) pair.
//
// Seeds running_x/y[bucket_global] from val_idx[row_begin] for non-empty
// buckets and sets:
//   - bucket_cursor[bucket_global] = row_begin + 1 (for non-empty)
//                                  = row_end       (for empty)
//   - bucket_active[bucket_global] = 1 / 0
//
// Cursor stores the SUBTASK-RELATIVE k value (range [row_begin, row_end))
// — same convention the legacy SMVP uses internally. The schedule and
// apply_scatter kernels combine \`subtask_idx * input_size + cursor\` to
// reach into val_idx at dispatch time.

// row_ptr layout: (num_subtasks * (num_columns + 1)) entries.
// row_ptr[subtask_idx * (num_columns + 1) + bucket_local] = row_begin
@group(0) @binding(0)
var<storage, read> row_ptr: array<u32>;
// val_idx layout: (num_subtasks * input_size) entries.
@group(0) @binding(1)
var<storage, read> val_idx: array<u32>;
@group(0) @binding(2)
var<storage, read> new_point_x: array<BigInt>;
@group(0) @binding(3)
var<storage, read> new_point_y: array<BigInt>;

// Workspace: (num_subtasks * num_columns) entries.
// running_x/y[subtask_idx * num_columns + bucket_local] = current sum
@group(0) @binding(4)
var<storage, read_write> running_x: array<BigInt>;
@group(0) @binding(5)
var<storage, read_write> running_y: array<BigInt>;
@group(0) @binding(6)
var<storage, read_write> bucket_cursor: array<u32>;
@group(0) @binding(7)
var<storage, read_write> bucket_active: array<u32>;

// params[0] = total_buckets   (= num_subtasks * num_columns)
// params[1] = num_columns
// params[2] = input_size
// params[3] = unused
@group(0) @binding(8)
var<uniform> params: vec4<u32>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let bucket_global = global_id.x;
    let total_buckets = params[0];
    let num_columns = params[1];
    let input_size = params[2];

    if (bucket_global >= total_buckets) {
        return;
    }

    let subtask_idx = bucket_global / num_columns;
    let bucket_local = bucket_global % num_columns;

    let rp_offset = subtask_idx * (num_columns + 1u);
    let vi_offset = subtask_idx * input_size;

    let row_begin = row_ptr[rp_offset + bucket_local];
    let row_end = row_ptr[rp_offset + bucket_local + 1u];

    if (row_begin >= row_end) {
        // Empty bucket. Cursor at row_end so schedule skips it; active
        // = 0 marks it for finalize to ignore.
        bucket_cursor[bucket_global] = row_end;
        bucket_active[bucket_global] = 0u;
        return;
    }

    // Seed from first point in the bucket.
    let pt_idx = val_idx[vi_offset + row_begin];
    running_x[bucket_global] = new_point_x[pt_idx];
    running_y[bucket_global] = new_point_y[pt_idx];
    bucket_cursor[bucket_global] = row_begin + 1u;
    bucket_active[bucket_global] = 1u;

    {{{ recompile }}}
}
`;

export const batch_affine_schedule = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}

// Per-round scheduler for the batch-affine SMVP pipeline.
//
// Cross-subtask parallel dispatch: ONE dispatch per round covering ALL
// subtasks. Geometry: (ceil(num_columns / wg_size), 1, num_subtasks).
// Each subtask is a Z workgroup-row; one thread per (subtask, bucket)
// pair. The previous design ran a sequential t-loop on the host, paying
// ~30-50 µs/launch × T × MAX_ROUNDS × 3 stages ≈ 50-80 ms of pure CPU
// dispatch overhead at T=16, MAX_ROUNDS=32. Going parallel collapses
// that to MAX_ROUNDS × 3 ≈ 96 launches.
//
// Per-subtask pair pool: each subtask owns a slot range of length
// num_columns inside the shared pool. pair_counter is now T atomics
// (one per subtask) instead of one global. apply_scatter mirrors this
// layout.

@group(0) @binding(0)
var<storage, read> row_ptr: array<u32>;
@group(0) @binding(1)
var<storage, read> val_idx: array<u32>;
@group(0) @binding(2)
var<storage, read> new_point_x: array<BigInt>;
@group(0) @binding(3)
var<storage, read> running_x: array<BigInt>;

@group(0) @binding(4)
var<storage, read_write> bucket_cursor: array<u32>;
@group(0) @binding(5)
var<storage, read_write> pair_delta: array<BigInt>;
// pair_target_meta packs (bucket_global, q_cursor) per pair as TWO u32s.
//   pair_target_meta[2*i]     = bucket_global
//   pair_target_meta[2*i + 1] = q_cursor
// Stored as array<u32> rather than array<vec2<u32>> to sidestep
// occasional Dawn/Metal layout quirks with 8-byte vector elements
// in storage buffers. The on-disk byte layout is identical.
@group(0) @binding(6)
var<storage, read_write> pair_target_meta: array<u32>;
// One atomic counter per subtask. pair_counter[subtask_idx] gives the
// number of active pairs scheduled for that subtask in this round.
@group(0) @binding(7)
var<storage, read_write> pair_counter: array<atomic<u32>>;

// params[0] = num_columns
// params[1] = input_size
// params[2] = unused
// params[3] = unused
@group(0) @binding(8)
var<uniform> params: vec4<u32>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let bucket_local = global_id.x;
    let subtask_idx = global_id.z;
    let num_columns = params[0];
    let input_size = params[1];
    if (bucket_local >= num_columns) {
        return;
    }

    let bucket_global = subtask_idx * num_columns + bucket_local;
    let rp_offset = subtask_idx * (num_columns + 1u);
    let vi_offset = subtask_idx * input_size;

    let cursor = bucket_cursor[bucket_global];
    let row_end = row_ptr[rp_offset + bucket_local + 1u];
    if (cursor >= row_end) {
        return;
    }

    // Look up Q's index in new_point_x.
    let pt_idx = val_idx[vi_offset + cursor];
    var q_x: BigInt = new_point_x[pt_idx];
    var p_x: BigInt = running_x[bucket_global];

    // delta = Q.x - P.x. fr_sub returns canonical zero if Q.x == P.x.
    var delta: BigInt = fr_sub(&q_x, &p_x);

    // Collision check.
    var nonzero: bool = false;
    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        if (delta.limbs[i] != 0u) {
            nonzero = true;
            break;
        }
    }
    if (!nonzero) {
        // Collision (delta == 0). Skip silently — caller assumes SRS
        // inputs where this is statistically impossible.
        return;
    }

    // Reserve a pair slot atomically within this subtask's pool slice.
    let slot_local = atomicAdd(&pair_counter[subtask_idx], 1u);
    let slot_global = subtask_idx * num_columns + slot_local;

    pair_delta[slot_global] = delta;
    pair_target_meta[2u * slot_global] = bucket_global;
    pair_target_meta[2u * slot_global + 1u] = cursor;
    bucket_cursor[bucket_global] = cursor + 1u;

    {{{ recompile }}}
}
`;

export const batch_inverse = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}

// get_r returns Montgomery R (= the integer 1 in Montgomery form). Each
// main shader defines its own with \`r_limbs\` substitution; the
// fr_pow / fr_inv partials in fr_pow_funcs call it.
fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

// Montgomery's batch-inverse trick on the GPU.
//
// Given N input field elements (in Montgomery form), compute their N
// inverses sharing ONE field inversion. Cost:
//   - 2(N-1) montgomery_products for prefix products + suffix walk
//   - 1 fr_inv (~500 montgomery_products of overhead)
//
// THIS KERNEL IS SINGLE-THREADED (workgroup_size = 1, single dispatch).
// The work is inherently sequential under this formulation; parallelising
// it (Hillis-Steele scan with mont_prod, or per-workgroup chunking with a
// global merge) is a non-trivial follow-up if profiling shows this kernel
// dominates.
//
// N is read from \`count_buf[0]\` rather than a uniform so the calling
// orchestrator (smvp_batch_affine_gpu) can chain this kernel directly
// after the schedule kernel — no CPU round-trip to read pair_counter
// between rounds. When N == 0 (no work this round), the kernel exits
// immediately at top.

@group(0) @binding(0)
var<storage, read> inputs: array<BigInt>;

@group(0) @binding(1)
var<storage, read_write> prefix: array<BigInt>;

@group(0) @binding(2)
var<storage, read_write> outputs: array<BigInt>;

// count_buf[0] = N (read from the upstream pair_counter).
//
// Bound as atomic-storage and read via atomicLoad to guarantee that
// the value written by the schedule kernel via atomicAdd in the
// previous compute pass is visible here. Without atomic semantics,
// some Dawn / Metal implementations have shown cross-shader
// visibility quirks for buffers re-bound with a different (non-
// atomic) view.
@group(0) @binding(3)
var<storage, read_write> count_buf: array<atomic<u32>>;

@compute
@workgroup_size(1)
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    if (global_id.x != 0u) {
        return;
    }

    let n = atomicLoad(&count_buf[0]);
    if (n == 0u) {
        return;
    }

    // Step 1: prefix products.
    var acc: BigInt = inputs[0];
    prefix[0] = acc;
    for (var i = 1u; i < n; i = i + 1u) {
        var a_i: BigInt = inputs[i];
        acc = montgomery_product(&acc, &a_i);
        prefix[i] = acc;
    }

    // Step 2: invert the final product.
    var inv_acc: BigInt = fr_inv(acc);

    // Step 3: walk back, emitting individual inverses.
    for (var idx = 0u; idx < n - 1u; idx = idx + 1u) {
        let i = n - 1u - idx;
        var prev: BigInt = prefix[i - 1u];
        var out_i: BigInt = montgomery_product(&inv_acc, &prev);
        outputs[i] = out_i;

        var a_i: BigInt = inputs[i];
        inv_acc = montgomery_product(&inv_acc, &a_i);
    }
    outputs[0] = inv_acc;

    {{{ recompile }}}
}
`;

export const batch_inverse_parallel = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> fr_pow_funcs }}

// Parallel Montgomery batch-inverse on the GPU.
//
// Replaces the single-threaded \`batch_inverse.template.wgsl\` (which
// dominated the SMVP wall time at ~243 ms per subtask × 16 subtasks
// = ~3.9 s of serial GPU work). This version does two-level scan
// (per-thread serial chunk + workgroup-level Hillis-Steele) in a single
// workgroup of TPB threads, dropping the per-dispatch cost from ~30 ms
// to ~1-3 ms at the realistic round sizes we see.
//
// MULTI-WORKGROUP MODE. The dispatch is shaped (NUM_SUB_WGS, 1, T).
// \`wid.z\` selects the subtask (count_buf[subtask]) and \`wid.x\` is the
// sub-workgroup index inside that subtask (0..NUM_SUB_WGS-1). Each
// sub-workgroup independently inverts a contiguous slice of length
// per_sub_chunk = ceil(n / NUM_SUB_WGS), using its own fr_inv. Reasoning:
//
//   - Phase A (per-thread fwd) and Phase D (per-thread back-walk) are
//     sequential per thread with bs = ceil(n / TPB). Splitting each
//     subtask across W sub-workgroups drops bs by W, giving up to W×
//     speedup on the dominant per-round latency at large N.
//
//   - Each sub-workgroup runs its own fr_inv. fr_invs across sub-WGs
//     run concurrently on different SMs, so the EXTRA fr_invs cost zero
//     wall time (gated only by SM occupancy). With T=16 subtasks × W=8
//     sub-WGs = 128 workgroups in flight, RTX-class GPUs are fully
//     occupied during the inverse pass.
//
// Two clients today:
//   - SMVP (cross-subtask): pitch = num_columns, count_buf[wid.z] =
//     pair_counter[wid.z] (per-subtask atomic).
//   - Finalize: pitch = half_num_columns, count_buf[wid.z] =
//     half_num_columns for all wid.z (pre-populated by host).
//
// Algorithm (Montgomery's batch-inverse trick, two-level):
//
//   1. Each thread i computes block_inclusive_prefix[k] for k in its
//      chunk into the \`prefix\` scratch buffer (serial, length bs =
//      ceil(n / TPB)). Captures block_total[i] in a register.
//   2. All TPB block_totals are pushed into workgroup memory.
//   3. Two parallel inclusive scans over wg memory: forward (wg_fwd)
//      and backward (wg_bwd). Hillis-Steele, log2(TPB) passes.
//      After scan:
//        wg_fwd[i] = block_total[0] * ... * block_total[i]
//        wg_bwd[i] = block_total[i] * ... * block_total[TPB-1]
//      So global_total = wg_fwd[TPB-1] = wg_bwd[0].
//   4. Thread 0 computes inv_global = inv(global_total) — single fr_inv.
//      Broadcast via wg_inv_total.
//   5. Each thread walks back through its chunk. The key trick: within
//      a single block, block_excl_prefix cancels algebraically, so the
//      back-walk reduces to the standard 2-mul/element batch inverse
//      on the per-block prefix array.
//
//        inv(global_prefix[k]) · global_prefix[k-1]
//          = inv(block_excl_prefix · P_in[k]) · (block_excl_prefix · P_in[k-1])
//          = inv(P_in[k]) · P_in[k-1]    // block_excl_prefix cancels
//
//      So:
//        block_excl_prefix[i] = wg_fwd[i-1] (or R for i=0)
//        block_excl_suffix[i] = wg_bwd[i+1] (or R for i=TPB-1)
//        // Setup: inv(block_total) = inv_global · block_excl_prefix · block_excl_suffix
//        inv_acc = inv(block_total[i])              // 2 muls (setup, one-time)
//        For k from chunk_end-1 down to chunk_start:
//          out[k] = inv_acc · (k>chunk_start ? prefix[k-1] : R)   // 1 mul (or 0)
//          inv_acc = inv_acc · inputs[k]                           // 1 mul
//
//      Cost: 2N muls in back-walk + N muls in forward + 2 muls setup
//      = 3N + O(1) per workgroup. Previously 3N + N back-walk muls
//      (extra mul-by-block_excl_prefix per element) = 4N total.
//
// TPB = 64 keeps workgroup memory at 2 * 64 * sizeof(BigInt) = 10240
// bytes (BN254: BigInt = 80 bytes), comfortably under the WebGPU
// default maxComputeWorkgroupStorageSize = 16384.
//
// When n == 0 for this workgroup the kernel returns immediately at the
// top.

const TPB: u32 = 64u;
const NUM_SUB_WGS: u32 = {{ num_sub_wgs }}u;

@group(0) @binding(0)
var<storage, read> inputs: array<BigInt>;

@group(0) @binding(1)
var<storage, read_write> prefix: array<BigInt>;

@group(0) @binding(2)
var<storage, read_write> outputs: array<BigInt>;

@group(0) @binding(3)
var<storage, read_write> count_buf: array<atomic<u32>>;

// params[0] = pitch (per-workgroup slice stride)
// params[1..3] = unused
@group(0) @binding(4)
var<uniform> params: vec4<u32>;

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

var<workgroup> wg_fwd: array<BigInt, TPB>;
var<workgroup> wg_bwd: array<BigInt, TPB>;
var<workgroup> wg_inv_total: BigInt;
// Broadcast slot for the pair count. atomicLoad returns a non-uniform
// value as far as the WGSL uniformity analysis is concerned, so the
// downstream \`workgroupBarrier()\`s would be ill-formed if we branched
// directly on it. Funnelling it through a workgroup variable + an
// explicit \`workgroupUniformLoad\` re-uniforms the value (and acts as
// an implicit barrier).
var<workgroup> wg_n: u32;
// Per-sub-WG element offset into the subtask's slice. Set by tid 0
// alongside wg_n; broadcast through workgroup memory so every thread
// agrees on the slice base. (workgroupUniformLoad over wg_n implicitly
// synchronises this write too, since both are written before the load.)
var<workgroup> wg_sub_offset: u32;

@compute
@workgroup_size(64)
fn main(
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let tid = lid.x;
    let pitch = params[0];
    let subtask_idx = wid.z;
    let sub_idx = wid.x;

    // Thread 0 reads the subtask's atomic count and the sub-WG's slice
    // bounds; broadcast via wg_n. workgroupUniformLoad ensures all
    // threads see a uniform \`n\` (= this sub-WG's element count) and
    // synchronises the workgroup before continuing.
    if (tid == 0u) {
        let total_n = atomicLoad(&count_buf[subtask_idx]);
        // Split [0, total_n) into NUM_SUB_WGS contiguous chunks. Chunks
        // are sized ceil(total_n / NUM_SUB_WGS); trailing sub-WGs may
        // see a shorter (or empty) chunk if total_n isn't a multiple of
        // NUM_SUB_WGS.
        let per_sub = (total_n + NUM_SUB_WGS - 1u) / NUM_SUB_WGS;
        let raw_start = sub_idx * per_sub;
        let raw_end = raw_start + per_sub;
        var sub_n: u32 = 0u;
        if (raw_start < total_n) {
            var clamped_end = raw_end;
            if (clamped_end > total_n) { clamped_end = total_n; }
            sub_n = clamped_end - raw_start;
        }
        wg_sub_offset = raw_start;
        wg_n = sub_n;
    }
    let n = workgroupUniformLoad(&wg_n);
    if (n == 0u) {
        return;
    }
    let sub_offset_in_subtask = wg_sub_offset;

    // Subtask owns a slice of \`pitch\` elements at offset
    // subtask_idx * pitch. This sub-WG owns
    // [subtask_offset + sub_offset_in_subtask,
    //  subtask_offset + sub_offset_in_subtask + n).
    let slice_offset = subtask_idx * pitch + sub_offset_in_subtask;

    // Block size = ceil(n / TPB). Last thread may have a shorter chunk.
    let bs = (n + TPB - 1u) / TPB;
    let chunk_start = tid * bs;
    var chunk_end = chunk_start + bs;
    if (chunk_end > n) {
        chunk_end = n;
    }

    // Phase A: per-thread inclusive prefix product over the chunk.
    // block_total = product of all elements in this thread's chunk,
    // or R (Montgomery 1) if the chunk is empty.
    var block_total: BigInt = get_r();
    if (chunk_start < n) {
        var acc: BigInt = inputs[slice_offset + chunk_start];
        prefix[slice_offset + chunk_start] = acc;
        for (var k = chunk_start + 1u; k < chunk_end; k = k + 1u) {
            var x: BigInt = inputs[slice_offset + k];
            acc = montgomery_product(&acc, &x);
            prefix[slice_offset + k] = acc;
        }
        block_total = acc;
    }

    wg_fwd[tid] = block_total;
    wg_bwd[tid] = block_total;
    workgroupBarrier();

    // Phase B: forward + backward inclusive scans on the TPB block_totals.
    // Hillis-Steele, log2(TPB) passes. Each pass: every thread reads two
    // values, multiplies, writes back.
    for (var stride: u32 = 1u; stride < TPB; stride = stride * 2u) {
        var fwd_x: BigInt = wg_fwd[tid];
        if (tid >= stride) {
            var lhs: BigInt = wg_fwd[tid - stride];
            fwd_x = montgomery_product(&lhs, &fwd_x);
        }
        var bwd_x: BigInt = wg_bwd[tid];
        if (tid + stride < TPB) {
            var rhs: BigInt = wg_bwd[tid + stride];
            bwd_x = montgomery_product(&bwd_x, &rhs);
        }
        workgroupBarrier();
        wg_fwd[tid] = fwd_x;
        wg_bwd[tid] = bwd_x;
        workgroupBarrier();
    }

    // Phase C: thread 0 inverts the global total. Broadcast via workgroup mem.
    if (tid == 0u) {
        var global_total: BigInt = wg_fwd[TPB - 1u];
        wg_inv_total = fr_inv(global_total);
    }
    workgroupBarrier();

    // Phase D: walk back through this thread's chunk, emitting inverses.
    if (chunk_start >= n) {
        return;
    }

    // block_excl_prefix[i] = product of block_totals[0..i-1]
    // block_excl_suffix[i] = product of block_totals[i+1..TPB-1]
    var block_excl_prefix: BigInt = get_r();
    if (tid > 0u) {
        block_excl_prefix = wg_fwd[tid - 1u];
    }
    var block_excl_suffix: BigInt = get_r();
    if (tid + 1u < TPB) {
        block_excl_suffix = wg_bwd[tid + 1u];
    }

    // Setup: inv_acc = inv(block_total[tid]) = inv(prefix_in_block[chunk_end-1])
    //   = inv_global * block_excl_prefix * block_excl_suffix
    // Costs 2 muls once, but lets the back-walk run as the standard
    // 2-mul/element batch inverse — saving 1 mul per element vs the
    // previous formulation that multiplied by block_excl_prefix every
    // iteration.
    var inv_global: BigInt = wg_inv_total;
    var inv_acc: BigInt = montgomery_product(&inv_global, &block_excl_prefix);
    inv_acc = montgomery_product(&inv_acc, &block_excl_suffix);

    // Walk from k = chunk_end-1 down to chunk_start. Within a block,
    // block_excl_prefix cancels algebraically (see header comment), so
    // we run the standard backward batch-inverse over the per-block
    // prefix array: 2 muls/element (1 output + 1 update).
    var k: u32 = chunk_end;
    while (k > chunk_start) {
        k = k - 1u;

        // out[k] = inv_acc * prefix_in_block[k-1]   (or inv_acc itself for k = chunk_start)
        var inv_a_k: BigInt;
        if (k > chunk_start) {
            var prev_in_block: BigInt = prefix[slice_offset + k - 1u];
            inv_a_k = montgomery_product(&inv_acc, &prev_in_block);
        } else {
            inv_a_k = inv_acc;
        }
        outputs[slice_offset + k] = inv_a_k;

        // Update: inv_acc <- inv_acc * a[k] = inv(prefix_in_block[k-1])
        // for the next iteration. The update on the last iteration
        // (k = chunk_start) is wasted — minor cost, kept for code
        // simplicity; the loop exit condition skips it naturally.
        if (k > chunk_start) {
            var a_k: BigInt = inputs[slice_offset + k];
            inv_acc = montgomery_product(&inv_acc, &a_k);
        }
    }

    {{{ recompile }}}
}
`;

