export const decompose_scalars_signed_only = `// Scalars-only variant of \`convert_point_coords_and_decompose_scalars\`.
// Reads 32-byte LE scalars from a packed u32 buffer and writes one
// shifted-signed bucket index per scalar per subtask into \`chunks\`.
//
// Purpose. Warm-path MSM with cached SRS bases: points are already in
// Montgomery form on the GPU, so we skip the Barrett + Mont work
// entirely and only need to decompose scalars. The resulting
// \`chunks_sb\` feeds the transpose → SMVP → BPR chain identically to
// the unified convert shader.
//
// Mirrors lines 88–129 of
// \`convert_point_coords_and_decompose_scalars.template.wgsl\` verbatim
// so downstream stages see byte-identical inputs.
//
// Optional fused count: when \`count_into_col_ptr\` is true, the kernel
// also atomicAdds into the per-subtask column-counter buffer (the same
// \`all_csc_col_ptr\` layout that the parallel transpose's count phase
// produces). This lets the orchestrator skip the separate
// transpose_count dispatch and saves one full pass over
// \`scalar_chunks_sb\` (~2 MB read + ~2 MB col_ptr atomic writes at
// N=2^16). Caller must zero \`col_ptr\` before this kernel runs and
// must NOT also dispatch transpose_count.

{{ > extract_word_from_bytes_le_funcs }}

@group(0) @binding(0)
var<storage, read> scalars: array<u32>;

@group(0) @binding(1)
var<storage, read_write> chunks: array<u32>;

@group(0) @binding(2)
var<uniform> input_size: u32;

{{#count_into_col_ptr}}
@group(0) @binding(3)
var<storage, read_write> col_ptr: array<atomic<u32>>;
{{/count_into_col_ptr}}

const NUM_SUBTASKS = {{ num_subtasks }}u;
const CHUNK_SIZE = {{ chunk_size }}u;
{{#count_into_col_ptr}}
const NUM_COLUMNS = {{ num_columns }}u;
{{/count_into_col_ptr}}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let gidx = global_id.x;
    let gidy = global_id.y;
    let id = gidx * {{ num_y_workgroups }}u + gidy;

    let INPUT_SIZE = input_size;

    var scalar_bytes: array<u32, 16>;
    for (var i = 0u; i < {{ scalar_u32_words }}u; i++) {
        let s = scalars[id * {{ scalar_u32_words }}u + i];
        let hi = s >> 16u;
        let lo = s & 65535u;
        scalar_bytes[15 - (i * 2)] = lo;
        scalar_bytes[15 - (i * 2) - 1] = hi;
    }

    var chunks_arr: array<u32, {{ num_subtasks }}>;
    for (var i = 0u; i < NUM_SUBTASKS; i++) {
        chunks_arr[i] = extract_word_from_bytes_le(scalar_bytes, i, CHUNK_SIZE);
    }
    {{#use_top_chunk_override}}
    // Override the top chunk for non-aligned bit lengths (e.g. BLS12-377
    // L=253, c=16 → top chunk must be 13 bits, not 16). The natural
    // extract reads beyond the scalar's high bit; this re-reads the
    // top with proper masking. Disabled when scalar_bitlength % chunk_size
    // == 0 (e.g. 256/16 or 128/16) where the natural extract is already
    // correct AND this override would zero-out the top chunk on
    // shorter scalar buffers (the GLV 128-bit case).
    chunks_arr[NUM_SUBTASKS - 1] = scalar_bytes[0] >> (((NUM_SUBTASKS * CHUNK_SIZE - {{ scalar_bitlength }}u) + 16u) - CHUNK_SIZE);
    {{/use_top_chunk_override}}

    let l = {{ num_columns }}u;
    let s = l / 2u;

    var signed_slices: array<i32, {{ num_subtasks }}>;
    var carry = 0u;
    for (var i = 0u; i < NUM_SUBTASKS; i ++) {
        signed_slices[i] = i32(chunks_arr[i] + carry);
        if (signed_slices[i] >= i32(s)) {
            signed_slices[i] = (i32(l) - signed_slices[i]) * -1i;
            carry = 1u;
        } else {
            carry = 0u;
        }
    }

    for (var i = 0u; i < NUM_SUBTASKS; i++) {
        let offset = i * INPUT_SIZE;
        let c = u32(signed_slices[i]) + s;
        chunks[id + offset] = c;
{{#count_into_col_ptr}}
        // Fused-count path: atomically increment the column counter
        // for (subtask=i, col=c). Layout matches transpose_count's
        // output: \`col_ptr[i * (NUM_COLUMNS + 1) + c + 1]\`. The +1
        // offset is the standard CSR convention (slot 0 holds 0; the
        // prefix-sum scan turns slot k+1 into the start of column k).
{{/count_into_col_ptr}}
{{#count_into_col_ptr}}
        atomicAdd(&col_ptr[i * (NUM_COLUMNS + 1u) + c + 1u], 1u);
{{/count_into_col_ptr}}
    }

    {{{ recompile }}}
}
`;

export const extract_word_from_bytes_le = `fn extract_word_from_coord_bytes_le(
    input: array<u32, {{ num_16_bit_words_per_coord }}>,
    word_idx: u32,
    chunk_size: u32
) -> u32 {
    var word = 0u;
    let start_byte_idx = {{ num_16_bit_words_per_coord }}u - 1u - ((word_idx * chunk_size + chunk_size) / 16u);
    let end_byte_idx = {{ num_16_bit_words_per_coord }}u - 1u - ((word_idx * chunk_size) / 16u);

    let start_byte_offset = (word_idx * chunk_size + chunk_size) % 16u;
    let end_byte_offset = (word_idx * chunk_size) % 16u;

    var mask = 0u;
    if (start_byte_offset > 0u) {
        mask = (2u << (start_byte_offset - 1u)) - 1u;
    }
    if (start_byte_idx == end_byte_idx) {
        word = (input[start_byte_idx] & mask) >> end_byte_offset;
    } else {
        word = (input[start_byte_idx] & mask) << (16u - end_byte_offset);
        word += input[end_byte_idx] >> end_byte_offset;
    }

    return word;
}

fn extract_word_from_bytes_le(
    input: array<u32, 16>,
    word_idx: u32,
    chunk_size: u32
) -> u32 {
    var word = 0u;
    let start_byte_idx = 15u - ((word_idx * chunk_size + chunk_size) / 16u);
    let end_byte_idx = 15u - ((word_idx * chunk_size) / 16u);

    let start_byte_offset = (word_idx * chunk_size + chunk_size) % 16u;
    let end_byte_offset = (word_idx * chunk_size) % 16u;

    var mask = 0u;
    if (start_byte_offset > 0u) {
        mask = (2u << (start_byte_offset - 1u)) - 1u;
    }
    if (start_byte_idx == end_byte_idx) {
        word = (input[start_byte_idx] & mask) >> end_byte_offset;
    } else {
        word = (input[start_byte_idx] & mask) << (16u - end_byte_offset);
        word += input[end_byte_idx] >> end_byte_offset;
    }

    return word;
}
`;

export const horner_reduce_bn254 = `{{> structs }}
{{> bigint_funcs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> ec_funcs }}

// GPU-side replacement for the CPU Horner reduction at the tail of the
// MSM. Two entry points dispatched in sequence:
//
//   subtask_reduce — T workgroups of TPB threads each. Workgroup k
//     reduces g_points[k*b_wg .. (k+1)*b_wg - 1] into one Jacobian
//     point and writes it to subtask_sums[k]. Each thread does a
//     serial chunk of (b_wg / TPB) adds, then cooperative tree
//     reduction in workgroup memory.
//
//   horner_chain — 1 workgroup, 1 thread. Reads subtask_sums[0..T-1]
//     and walks the Horner chain, writing the final result to
//     result_x/y/z[0].
//
// Why two kernels:
// - Inter-workgroup sync requires a dispatch boundary in WebGPU; we
//   need all subtask_sums written before the Horner chain can start.
// - The previous single-workgroup design ran all T subtask reductions
//   on a single SM (the workgroup's threads get packed into one Metal
//   SIMD group), which serialised the per-subtask 256-add chains.
//   Spreading subtasks across T workgroups parallelises across SMs.
//
// Compute budget (BN254, T=16, b_wg=256, chunk=16):
//   subtask_reduce: 16 workgroups × (256/32 + log2(32)) ≈ 13 adds/thread
//                   wall = 13 * (11M+5S) ≈ 200 muls × ~50 ns ≈ 10 µs
//   horner_chain:   16 doublings × 15 + 15 adds ≈ 17 mont-mul-equiv per
//                   chunk × 15 chunks ≈ 250 muls ≈ 12 µs
//   Total: ~25 µs wall time vs the previous ~45 ms (single-SM packed).

const TPB: u32 = 32u;
const B_WG_SIZE: u32 = {{ b_workgroup_size }}u;
const CHUNK_SIZE: u32 = {{ chunk_size }}u;
const T: u32 = {{ num_subtasks }}u;

@group(0) @binding(0)
var<storage, read> g_points_x: array<BigInt>;
@group(0) @binding(1)
var<storage, read> g_points_y: array<BigInt>;
@group(0) @binding(2)
var<storage, read> g_points_z: array<BigInt>;

// Combined scratch + result buffer (T+1 BigInts per coordinate):
//   index 0..T-1 — per-subtask partial sum (written by subtask_reduce,
//                  read by horner_chain).
//   index T     — final Horner result (written by horner_chain, read by CPU).
//
// Packing all three coordinates into one buffer pair (sums_x, sums_y, sums_z)
// instead of six separate buffers keeps us within the 8-storage-buffers-
// per-stage WebGPU baseline (current shader: 3 read-only g_points +
// 3 read-write packed = 6 storage bindings).
@group(0) @binding(3)
var<storage, read_write> sums_x: array<BigInt>;
@group(0) @binding(4)
var<storage, read_write> sums_y: array<BigInt>;
@group(0) @binding(5)
var<storage, read_write> sums_z: array<BigInt>;

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

fn get_paf() -> Point {
    var p: Point;
    p.y = get_r();
    return p;
}

// Workgroup memory for tree reduction. TPB partial sums × sizeof(Point).
// At TPB=32: 32 * 240 = 7680 bytes — half of the 16 KB default cap.
var<workgroup> wg_partials: array<Point, TPB>;

@compute
@workgroup_size(TPB)
fn subtask_reduce(
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let tid = lid.x;
    let subtask_idx = wid.x;
    let base = subtask_idx * B_WG_SIZE;

    // Per-thread serial chunk: each thread sums its slice of (b_wg / TPB)
    // points. With b_wg=256 and TPB=32, that's 8 adds per thread.
    let chunk = B_WG_SIZE / TPB;
    let chunk_start = tid * chunk;
    var acc: Point = get_paf();
    for (var i: u32 = 0u; i < chunk; i = i + 1u) {
        let idx = base + chunk_start + i;
        var p: Point;
        p.x = g_points_x[idx];
        p.y = g_points_y[idx];
        p.z = g_points_z[idx];
        acc = add_points(acc, p);
    }
    wg_partials[tid] = acc;

    workgroupBarrier();

    // Tree reduction: log2(TPB) passes of halve-and-add.
    var stride: u32 = TPB / 2u;
    while (stride > 0u) {
        if (tid < stride) {
            let other = wg_partials[tid + stride];
            wg_partials[tid] = add_points(wg_partials[tid], other);
        }
        workgroupBarrier();
        stride = stride / 2u;
    }

    // Thread 0 writes this subtask's sum at slot subtask_idx.
    if (tid == 0u) {
        let s = wg_partials[0];
        sums_x[subtask_idx] = s.x;
        sums_y[subtask_idx] = s.y;
        sums_z[subtask_idx] = s.z;
    }

    {{{ recompile }}}
}

// Final-result slot index (T-th element of sums_*). Caller reads back
// these three positions to recover the MSM result.
const RESULT_SLOT: u32 = {{ num_subtasks }}u;

// Parallel Horner chain. The serial Horner walk
//   result = s[T-1]; for j=T-2..0: result = result*2^cs + s[j]
// expands to:
//   result = Σ_{j=0..T-1} subtask_sums[j] · 2^(j · CHUNK_SIZE)
// (s[T-1] is multiplied by 2^cs once per loop iter, s[T-2] T-2 times,
// ..., s[0] zero times — coefficient of s[j] is 2^(j·cs).)
//
// Each thread tid takes subtask_sums[tid] and applies tid · CHUNK_SIZE
// doublings. A workgroup tree-reduce then sums the T scaled points.
//
// Wall time vs the previous workgroup_size=1 design: each thread runs
// at most (T-1)·CHUNK_SIZE doublings (≤ 240 for production), but all T
// threads execute in lockstep within one Metal SIMD group, replacing
// 240 single-threaded doublings on idle hardware. Roughly 10× speedup.
//
// Workgroup memory: reuses wg_partials[0..T-1]. T ≤ TPB by construction.
@compute
@workgroup_size({{ num_subtasks }})
fn horner_chain(@builtin(local_invocation_id) lid: vec3<u32>) {
    let tid = lid.x;

    // Load subtask_sums[tid] and apply tid·CHUNK_SIZE doublings.
    var p: Point;
    p.x = sums_x[tid];
    p.y = sums_y[tid];
    p.z = sums_z[tid];
    let n_doublings = tid * CHUNK_SIZE;
    for (var i: u32 = 0u; i < n_doublings; i = i + 1u) {
        p = double_point(p);
    }
    wg_partials[tid] = p;

    workgroupBarrier();

    // Tree reduce: log2(T) passes of halve-and-add.
    var stride: u32 = T / 2u;
    while (stride > 0u) {
        if (tid < stride) {
            wg_partials[tid] = add_points(wg_partials[tid], wg_partials[tid + stride]);
        }
        workgroupBarrier();
        stride = stride / 2u;
    }

    // Thread 0 writes the final result.
    if (tid == 0u) {
        let r = wg_partials[0];
        sums_x[RESULT_SLOT] = r.x;
        sums_y[RESULT_SLOT] = r.y;
        sums_z[RESULT_SLOT] = r.z;
    }

    {{{ recompile }}}
}
`;

export const smvp_bn254 = `{{> structs }}
{{> montgomery_product_funcs }}
{{> field_funcs }}
{{> bigint_funcs }}
{{> ec_funcs }}

// Input buffers
@group(0) @binding(0)
var<storage, read> row_ptr: array<u32>;
@group(0) @binding(1)
var<storage, read> val_idx: array<u32>;
@group(0) @binding(2)
var<storage, read> new_point_x: array<BigInt>;
@group(0) @binding(3)
var<storage, read> new_point_y: array<BigInt>;

// Output buffers
@group(0) @binding(4)
var<storage, read_write> bucket_x: array<BigInt>;
@group(0) @binding(5)
var<storage, read_write> bucket_y: array<BigInt>;
@group(0) @binding(6)
var<storage, read_write> bucket_z: array<BigInt>;

// Params buffer
@group(0) @binding(7)
var<uniform> params: vec4<u32>;

fn get_r() -> BigInt {
    var r: BigInt;
{{{ r_limbs }}}
    return r;
}

fn get_paf() -> Point {
    var result: Point;
    result.y = get_r();
    return result;
}

// This double-and-add code is adapted from the ZPrize test harness:
// https://github.com/demox-labs/webgpu-msm/blob/main/src/reference/webgpu/wgsl/Curve.ts#L78
fn double_and_add(point: Point, scalar: u32) -> Point {
    // Set result to the point at infinity
    var result: Point = get_paf();

    var s = scalar;
    var temp = point;

    while (s != 0u) {
        if ((s & 1u) == 1u) {
            result = add_points(result, temp);
        }
        temp = double_point(temp);
        s = s >> 1u;
    }
    return result;
}

// Point negation only involves multiplying the Y coordinate by -1 in
// the field
fn negate_point(point: Point) -> Point {
    var p = get_p();
    var y = point.y;
    var neg_y: BigInt;
    bigint_sub(&p, &y, &neg_y);
    return Point(point.x, neg_y, point.z);
}

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let input_size = params[0];
    let num_y_workgroups = params[1];
    let num_z_workgroups = params[2];
    let subtask_offset = params[3];

    let gidx = global_id.x;
    let gidy = global_id.y;
    var gidz = global_id.z;
    let id = (gidx * num_y_workgroups + gidy) * num_z_workgroups + gidz;

    let num_columns = {{ num_columns }}u;
    let l = num_columns;
    let h = {{ half_num_columns }}u;

    // Define custom subtask_idx
    let subtask_idx = (id / h);

    var inf = get_paf();

    let rp_offset = (subtask_idx + subtask_offset) * (num_columns + 1u);

    // As we use the signed bucket index technique, each thread handles two
    // buckets.
    for (var j = 0u; j < 2u; j ++) {
        var row_idx = (id % h) + h;
        if (j == 1u) {
            row_idx = h - (id % h);
        }

        if (j == 0u && id % h == 0u) {
            row_idx = 0u;
        }

        // Skip the chunk=0 row (row h). The (j=1, id%h=0) thread would
        // otherwise iterate through every scalar whose signed chunk is 0
        // — at the top subtask of BN254 Fr this is nearly all of them
        // (random Fr < 2^254 means chunk_17's top bits are zero, and most
        // scalars don't propagate a carry that far) — and write nothing
        // because bucket_idx = 0 is the "no contribution" sentinel. One
        // thread spinning through n/2 mixed-adds is enough to trip
        // Chrome's GPU-process watchdog at n >= 2^17, dropping the device
        // and leaving bucket buffers at their initial (zero) state. Bail
        // before the inner loop runs.
        if (j == 1u && id % h == 0u) {
            continue;
        }

        let row_begin = row_ptr[rp_offset + row_idx];
        let row_end = row_ptr[rp_offset + row_idx + 1u];
        var sum = inf;

        // Add up all the points in the bucket.
        //
        // Jacobian-mixed-add hot path: every \`pt\` loaded here has Z = R
        // (Montgomery 1) by construction, so we call \`add_points_mixed\`
        // which uses the Z2=1 formula (7M+4S) instead of the general
        // Jacobian add (11M+5S). \`pt.z\` is ignored by add_points_mixed —
        // we still set it so the Point struct is fully initialised.
        //
        // Use the NO-COLLISION variant: SRS bases are linearly independent
        // random points in G1, so the running bucket sum can never
        // affinely equal a fresh SRS point being added (would require a
        // discrete-log accident). Saves 2 × bigint_eq per call. The
        // identity short-circuit at the top of the function is kept
        // (genuine: first iter has sum.z == 0).
        for (var k = row_begin; k < row_end; k ++) {
            let idx = val_idx[(subtask_idx + subtask_offset) * input_size + k];

            var x = new_point_x[idx];
            var y = new_point_y[idx];
            var z = get_r();
            let pt = Point(x, y, z);

            sum = add_points_mixed_no_collision(sum, pt);
        }

        // Negate the point if the recovered bucket index is negative.
        // Since we've added half_num_columns to each scalar chunk in
        // convert_point_coords_and_decompose_scalars.template.wgsl, we know if
        // the original bucket index is negative if it is less than
        // half_num_columns.
        var bucket_idx = 0u;
        if (h > row_idx) {
            bucket_idx = h - row_idx;
            sum = negate_point(sum);
        } else {
            bucket_idx = row_idx - h;
        }

        let bi = id + subtask_offset * h;

        if (bucket_idx > 0u) {
            // Store the result in buckets[thread_id]. Each thread must use
            // a unique storage location (thread_id) to prevent race
            // conditions.
            if (j == 1) {
                // Since the point has been set, add to it.
                let bucket = Point(
                    bucket_x[bi],
                    bucket_y[bi],
                    bucket_z[bi]
                );
                sum = add_points(bucket, sum);
            }

            // Set the point. Since no point has been set when j == 0, we can just
            // overwrite the data.
            bucket_x[bi] = sum.x;
            bucket_y[bi] = sum.y;
            bucket_z[bi] = sum.z;
        }
    }

    {{{ recompile }}}
}
`;

export const transpose_parallel_count = `// Parallel transpose — Phase 1 of 3: count nonzeros per column.
//
// Splits the per-subtask serial transpose into three independent kernels.
// At N=2^16, the original single-thread-per-subtask pass measured ~65 ms
// of GPU time (one quarter of total). The three-phase variant moves
// counting and scattering to n*T threads (1M+ at N=2^16, T=16) while
// keeping the prefix-sum scan in T threads (cheap: ~64k ops/thread).
//
// Phase 1 contract:
//   - Input: all_csr_col_idx[T * n] — same as the serial path.
//   - Output: all_csc_col_ptr[T * (n_cols + 1)] holds, after this kernel,
//     \`count[col + 1]\` for each (subtask, col) pair (entry 0 of each
//     subtask is left at 0). Bit-identical to what the serial transpose
//     leaves between its line-54 count loop and its line-58 scan loop.
//
// Dispatch: input_size threads in X × num_subtasks in Y. One thread per
// (i, subtask) pair.

@group(0) @binding(0)
var<storage, read> all_csr_col_idx: array<u32>;

@group(0) @binding(1)
var<storage, read_write> all_csc_col_ptr: array<atomic<u32>>;

@group(0) @binding(2)
var<uniform> params: vec3<u32>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let i = global_id.x;
    let subtask_idx = global_id.y;

    let n = params[1];
    let input_size = params[2];

    if (i >= input_size) {
        return;
    }

    let ccp_offset = subtask_idx * (n + 1u);
    let cci_offset = subtask_idx * input_size;

    let col = all_csr_col_idx[cci_offset + i];
    atomicAdd(&all_csc_col_ptr[ccp_offset + col + 1u], 1u);

    {{{ recompile }}}
}
`;

export const transpose_parallel_scan = `// Parallel transpose — Phase 2 of 3: in-place inclusive prefix sum
// (scan) of per-column counts → per-column start offsets.
//
// One *workgroup* per subtask, 256 threads per workgroup, each thread
// handles ceil((n_cols + 1) / 256) elements. Standard three-phase
// chunked scan:
//
//   A. Each thread sums its chunk into a local register; thread sums go
//      into workgroup-shared memory.
//   B. Workgroup-level inclusive scan over the 256 thread sums via
//      Hillis–Steele (O(N log N) work but log N depth — fine at N=256).
//      Convert to exclusive prefix per thread.
//   C. Each thread re-reads its chunk and writes inclusive prefix-sum
//      values starting from its block prefix.
//
// Replaces the previous serial-per-subtask scan that measured 37 ms of
// GPU time at N=2^16 (the new dominant cost after the parallel
// count/scatter dispatches dropped to <0.5 ms each). Expected to drop
// to ~1-2 ms with full workgroup parallelism.
//
// Bit-equivalent output to the serial scan in transpose_serial.wgsl
// lines 58-61: csc_col_ptr[k] = sum_{j=0}^{k-1} count(j) for k in [0, n].
// (Inclusive scan over the array where csc_col_ptr[0] = 0 and
// csc_col_ptr[i] = count(i-1) for i >= 1.)

const SCAN_WG_SIZE = 256u;

@group(0) @binding(0)
var<storage, read_write> all_csc_col_ptr: array<atomic<u32>>;

@group(0) @binding(1)
var<uniform> params: vec3<u32>;

var<workgroup> wg_sums: array<u32, SCAN_WG_SIZE>;

@compute
@workgroup_size(SCAN_WG_SIZE)
fn main(
    @builtin(local_invocation_id) lid: vec3<u32>,
    @builtin(workgroup_id) wid: vec3<u32>,
) {
    let tid = lid.x;
    let subtask_idx = wid.x;

    let n = params[1];
    let n_plus_1 = n + 1u;
    let base = subtask_idx * n_plus_1;

    let chunk_size = (n_plus_1 + SCAN_WG_SIZE - 1u) / SCAN_WG_SIZE;
    let chunk_start = tid * chunk_size;
    var chunk_end = chunk_start + chunk_size;
    if (chunk_end > n_plus_1) {
        chunk_end = n_plus_1;
    }

    // Phase A: compute this thread's chunk-local sum.
    var local_sum: u32 = 0u;
    for (var i = chunk_start; i < chunk_end; i = i + 1u) {
        local_sum = local_sum + atomicLoad(&all_csc_col_ptr[base + i]);
    }
    wg_sums[tid] = local_sum;
    workgroupBarrier();

    // Phase B: Hillis–Steele inclusive scan over wg_sums.
    for (var stride = 1u; stride < SCAN_WG_SIZE; stride = stride * 2u) {
        var x = wg_sums[tid];
        if (tid >= stride) {
            x = x + wg_sums[tid - stride];
        }
        workgroupBarrier();
        wg_sums[tid] = x;
        workgroupBarrier();
    }
    // After the loop, wg_sums[tid] = inclusive scan up through tid.
    // The exclusive prefix is wg_sums[tid] - local_sum.
    let block_prefix = wg_sums[tid] - local_sum;

    // Phase C: in-place inclusive prefix scan over this thread's chunk,
    // starting from block_prefix. The serial version did exactly the
    // same in-place inclusive write; the only race-free constraint is
    // that distinct threads operate on disjoint chunks, which holds by
    // construction here.
    var running = block_prefix;
    for (var i = chunk_start; i < chunk_end; i = i + 1u) {
        running = running + atomicLoad(&all_csc_col_ptr[base + i]);
        atomicStore(&all_csc_col_ptr[base + i], running);
    }

    {{{ recompile }}}
}
`;

export const transpose_parallel_scatter = `// Parallel transpose — Phase 3 of 3: scatter point indices into their
// CSC slot.
//
// At this point all_csc_col_ptr holds the per-column start offsets
// (Phase 2 output), and all_curr is zero. For each (i, subtask), look
// up col = csr_col_idx[i], reserve a slot via atomicAdd on
// all_curr[col], and write i into all_csc_val_idxs at
// (col_ptr[col] + slot).
//
// Bit-for-bit equivalent to the serial scatter loop in
// transpose_serial.wgsl lines 67-73, modulo the within-column ordering:
// the parallel version may store points within a column in arrival
// order across the n*T threads, whereas the serial version stores them
// in i-ascending order. Downstream SMVP doesn't depend on per-column
// ordering — it iterates the whole bucket — so this is invisible.
//
// Dispatch: input_size threads in X × num_subtasks in Y. One thread
// per (i, subtask) pair.

@group(0) @binding(0)
var<storage, read> all_csr_col_idx: array<u32>;

// Read-only at this stage (offsets, computed by the scan kernel).
@group(0) @binding(1)
var<storage, read> all_csc_col_ptr: array<u32>;

@group(0) @binding(2)
var<storage, read_write> all_csc_val_idxs: array<u32>;

// Per-column write counters; initially 0, atomicAdd'd to find each
// thread's slot.
@group(0) @binding(3)
var<storage, read_write> all_curr: array<atomic<u32>>;

@group(0) @binding(4)
var<uniform> params: vec3<u32>;

@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {
    let i = global_id.x;
    let subtask_idx = global_id.y;

    let n = params[1];
    let input_size = params[2];

    if (i >= input_size) {
        return;
    }

    let ccp_offset = subtask_idx * (n + 1u);
    let cci_offset = subtask_idx * input_size;
    let curr_offset = subtask_idx * n;

    let col = all_csr_col_idx[cci_offset + i];
    let local_slot = atomicAdd(&all_curr[curr_offset + col], 1u);
    let global_slot = all_csc_col_ptr[ccp_offset + col] + local_slot;
    all_csc_val_idxs[cci_offset + global_slot] = i;

    {{{ recompile }}}
}
`;

export const transpose_serial = `/// Input storage buffers.
@group(0) @binding(0)
var<storage, read> all_csr_col_idx: array<u32>;

/// Output storage buffers.
@group(0) @binding(1)
var<storage, read_write> all_csc_col_ptr: array<atomic<u32>>;
@group(0) @binding(2)
var<storage, read_write> all_csc_val_idxs: array<u32>;

/// Intermediate storage buffer.
@group(0) @binding(3)
var<storage, read_write> all_curr: array<u32>;

/// Uniform storage buffer. Used instead of shader template constants
/// to avoid recompiling the shader if either value changes.
@group(0) @binding(4)
var<uniform> params: vec3<u32>;

/// Serial transpose algo adapted from Wang et al, 2016, "Parallel
/// Transposition of Sparse Data Structures".
/// https://synergy.cs.vt.edu/pubs/papers/wang-transposition-ics16.pdf

/// This shader implements a serial transpose algorithm, but each thread in
/// the workgroup handles the CSR matrix for a subtask, so num_subtasks
/// transpositions happen in parallel.

/// Note that there is no csr_row_ptr input buffer; rather, we calculate it
/// on the fly using calc_start_end. We also do not rearrange the nonzero
/// elements in-place, but instead output an array of their new positions
/// (all_csc_val_idxs).
@compute
@workgroup_size({{ workgroup_size }})
fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {    
    /// Subtask id.
    let subtask_idx = global_id.x;

    /// Number of rows.
    let m = params[0];

    /// Number of columns.
    let n = params[1];

    /// Input size.
    let input_size = params[2];

    /// Index offsets depending on the subtask ID (aka thread ID) and the slice length.
    let ccp_offset = subtask_idx * (n + 1u);
    let cci_offset = subtask_idx * input_size;
    let curr_offset = subtask_idx * n;

    /// "Count the number of nonzero elements in each column" (Wang et al, 2016).
    for (var j = 0u; j < input_size; j++) {
        atomicAdd(&all_csc_col_ptr[ccp_offset + all_csr_col_idx[cci_offset + j] + 1u], 1u);
    }

    /// Prefix sum, aka cumulative/incremental sum.
    for (var i = 1u; i < n + 1u; i++) {
        var incremental_sum = atomicLoad(&all_csc_col_ptr[ccp_offset + i - 1u]);
        atomicAdd(&all_csc_col_ptr[ccp_offset + i], incremental_sum);
    }

    /// "Traverse the nonzero elements again and move them to their final
    /// positions determined by the column offsets in csc_col_ptr and their
    /// current relative positions in curr." (Wang et al, 2016).
    var val = 0u;
    for (var j = 0u; j < input_size; j++) {
        var loc = atomicLoad(&all_csc_col_ptr[ccp_offset + all_csr_col_idx[cci_offset + j]]);
        loc += all_curr[curr_offset + all_csr_col_idx[cci_offset + j]];
        all_curr[curr_offset + all_csr_col_idx[cci_offset + j]]++;
        all_csc_val_idxs[cci_offset + loc] = val;
        val++;
    }

    {{{ recompile }}}
}`;

export const field = `fn fr_add(a: ptr<function, BigInt>, b: ptr<function, BigInt>) -> BigInt { 
    var res: BigInt;
    bigint_add(a, b, &res);
    return fr_reduce(&res);
}

fn fr_reduce(a: ptr<function, BigInt>) -> BigInt {
    var res: BigInt;
    var p: BigInt = get_p();
    var underflow = bigint_sub(a, &p, &res);
    if (underflow == 1u) {
        return *a;
    }

    return res;
}

fn fr_sub(a: ptr<function, BigInt>, b: ptr<function, BigInt>) -> BigInt {
    var res: BigInt;

    // Short-circuit a == b to canonical 0. Without this, the "a < b" branch
    // below would return p - (b - a) = p - 0 = p (value 0 mod p but limbs
    // != 0), which breaks is_zero() checks downstream in the EC shaders.
    if (bigint_eq(a, b)) {
        return res; // fresh BigInt, limbs all 0
    }

    var c = bigint_gt(a, b);
    if (c == 0u) { // a < b
        var r: BigInt;
        bigint_sub(b, a, &r);
        var p = get_p();
        bigint_sub(&p, &r, &res);
        return res;
    } else { // a > b
        bigint_sub(a, b, &res);
        return res;
    }
}
`;

export const fr_pow = `// Field exponentiation and inversion.
//
// Inputs/outputs are in Montgomery form. The Montgomery representative
// of 1 is R itself (since x*R mod p stores the integer x; 1*R = R), so
// \`get_r()\` is the multiplicative identity here.
//
// \`fr_inv\` is the hot fr operation in the batch-affine pipeline — it's
// the single sequential dependency at the centre of every batch_inverse
// dispatch (one call on tid=0 per workgroup, with the other 63 threads
// blocked at workgroupBarrier waiting). For BN254 with the previous
// Fermat / square-and-multiply implementation this was ~514 montgomery
// products per call, dominating mid-to-late round costs once N drops
// below ~1K. The binary extended GCD path below replaces it with ~256
// outer iterations of cheap BigInt shift / add / sub, plus ONE final
// montgomery_product to convert the native-form result back into
// Montgomery form. About 5-8× faster on the serial path.

// Generic Montgomery-form exponentiation, kept as a fallback / utility.
// Square-and-multiply over the limb-level bits of \`exp\`. Used by tests
// (the fr_pow / fr_inv Jest transcription) but no longer the primary
// fr_inv backbone.
fn fr_pow(base: BigInt, exp: BigInt) -> BigInt {
    var result: BigInt = get_r();   // Montgomery 1
    var b: BigInt = base;

    for (var i = 0u; i < NUM_WORDS; i = i + 1u) {
        for (var j = 0u; j < WORD_SIZE; j = j + 1u) {
            if (((exp.limbs[i] >> j) & 1u) == 1u) {
                result = montgomery_product(&result, &b);
            }
            b = montgomery_product(&b, &b);
        }
    }
    return result;
}

// R^3 mod p. Used by \`fr_inv\` to convert the binary-GCD output (which is
// in native form, pre-multiplied by R^(-1) because the input was in
// Montgomery form) back into Montgomery form via a single
// montgomery_product. See the derivation in the fr_inv body.
fn get_r_cubed() -> BigInt {
    var r3: BigInt;
{{{ r_cubed_limbs }}}
    return r3;
}

// Field inversion via Pornin's jumpy safegcd (Bernstein-Yang with K-step
// inner divsteps). https://eprint.iacr.org/2020/972
//
// Input \`a\` is in Montgomery form (encoding integer A = a · R mod p).
// Output is Montgomery form mont(a^(-1)) = a^(-1) · R mod p.
//
// === Algorithm overview ===
//
// State: (f, g, u, v, delta) where
//   - f, g: 2's complement signed BigInts on NUM_WORDS·WORD_SIZE = 260
//     bits. f starts as p, g as A. Bernstein-Yang invariant guarantees
//     |f|, |g| ≤ p < 2^254 throughout (6 spare bits including sign).
//   - u, v: in [0, p), canonical. Track M[0][1] mod p and M[1][1] mod p
//     of the cumulative transformation matrix.
//   - delta: signed i32 driving the step choice.
//
// Each OUTER iteration:
//   1. Extract the low WORD_SIZE bits of f, g into i32 approximations
//      (f_inner, g_inner). Run K=12 INNER divsteps on these — cheap
//      i32 operations — while accumulating an unscaled integer matrix
//      [[u00, u01], [u10, u11]] with entries bounded by 2^K. The
//      divstep CHOICES only depend on (delta, g & 1), and the low K+1
//      bits of g preserve g's low-bit evolution through K steps, so
//      the matrix from the inner loop equals what plain safegcd would
//      have built over K steps.
//
//   2. Apply the matrix to full (f, g) via signed multi-limb mul + arith
//      shift right by K (\`bigint_signed_axby_shr_k\`):
//        new_f = (u00 · f + u01 · g) >> K
//        new_g = (u10 · f + u11 · g) >> K
//      Divisibility by 2^K is guaranteed by the algorithm; the shift
//      is exact.
//
//   3. Apply the matrix mod p to (u, v) via the generalized m-trick
//      (\`bigint_signed_axby_modp_halve_k\`):
//        new_u = halve_mod_p((u00 · u + u01 · v), K)
//        new_v = halve_mod_p((u10 · u + u11 · v), K)
//
// === Iteration count ===
//
// Pornin's Theorem 11.2 bound: ⌈(49n + 80) / (17 · K)⌉ outer iterations
// suffice for n-bit inputs. For BN254 (n=254), K=12: ⌈61.4⌉ = 62. Cap
// at 70 for safety.
//
// === Why K=12 ===
//
//   - The approximation needs K+1 = 13 bits of low-bit fidelity, which
//     is exactly one WORD_SIZE limb (limbs[0]).
//   - Matrix entries bounded by 2^K = 4096 fit in i16, with i32 used
//     for arithmetic headroom (subtractions can briefly hit 2^(K+1)).
//   - Per-limb products in the matrix application: limb (2^13) ·
//     matrix_entry (2^12) = 2^25; sum of 2 + carry ≤ 2^27, fits in i32.
//   - \`bigint_halve_k_mod_p\`'s K < WORD_SIZE precondition is satisfied.
//
// === Comparison to plain safegcd (the previous fr_inv) ===
//
// Plain safegcd: ~737 outer iter × ~4 BigInt-equivalent ops/iter.
// Jumpy K=12:    ~62 outer iter × ~10 BigInt-equivalent ops/iter
//                                  (4 muls + accumulate + shift + mod-p
//                                  normalisation), plus ~120 cheap i32
//                                  ops for the inner loop.
//
// Estimated speedup on the critical path: ~2-3× vs plain safegcd in
// total BigInt-op count, depending on how the GPU pipelines the inner
// loop and the multi-limb axby calls.
//
// The previous plain safegcd is kept available as \`fr_inv_plain\` for
// A/B comparison; the previous binary-GCD-with-T1.b/c is \`fr_inv_bgcd\`.
fn fr_inv(a: BigInt) -> BigInt {
    const JUMPY_K: u32 = 12u;
    const JUMPY_MAX_OUTER: u32 = 70u;

    var f: BigInt = get_p();
    var g: BigInt = a;
    var u: BigInt;             // 0 (default-init)
    var v: BigInt;
    v.limbs[0] = 1u;           // 1
    var delta: i32 = 1;

    var p_const: BigInt = get_p();

    var found = false;
    for (var outer_iter: u32 = 0u; outer_iter < JUMPY_MAX_OUTER; outer_iter = outer_iter + 1u) {
        if (bigint_is_zero(&g)) {
            found = true;
            break;
        }

        // Inner loop: K divsteps on (f.limbs[0], g.limbs[0]) treated as
        // i32 approximations. Builds the unscaled 2x2 matrix.
        var u00: i32 = 1i; var u01: i32 = 0i;
        var u10: i32 = 0i; var u11: i32 = 1i;
        var f_inner: i32 = i32(f.limbs[0]);
        var g_inner: i32 = i32(g.limbs[0]);
        var inner_delta: i32 = delta;
        for (var i: u32 = 0u; i < JUMPY_K; i = i + 1u) {
            let g_low: i32 = g_inner & 1i;
            let take_swap: bool = (inner_delta > 0i) && (g_low == 1i);
            if (take_swap) {
                // M_step_unscaled = [[0, 2], [-1, 1]]
                let new_u00: i32 = u10 * 2i;
                let new_u01: i32 = u11 * 2i;
                let new_u10: i32 = u10 - u00;
                let new_u11: i32 = u11 - u01;
                u00 = new_u00; u01 = new_u01;
                u10 = new_u10; u11 = new_u11;

                let new_f: i32 = g_inner;
                g_inner = g_inner - f_inner;
                f_inner = new_f;
                inner_delta = 1i - inner_delta;
            } else if (g_low == 1i) {
                // M_step_unscaled = [[2, 0], [1, 1]]; top row doubles,
                // bottom row gets +(top row).
                u10 = u00 + u10;
                u11 = u01 + u11;
                u00 = u00 * 2i;
                u01 = u01 * 2i;
                g_inner = g_inner + f_inner;
                inner_delta = inner_delta + 1i;
            } else {
                // M_step_unscaled = [[2, 0], [0, 1]]; only top row doubles.
                u00 = u00 * 2i;
                u01 = u01 * 2i;
                inner_delta = inner_delta + 1i;
            }
            // Halve g_inner (arith shr 1).
            g_inner = g_inner >> 1u;
        }
        delta = inner_delta;

        // Apply matrix to (f, g): full multi-limb signed mul + arith shr K.
        var new_f: BigInt;
        var new_g: BigInt;
        bigint_signed_axby_shr_k(&f, u00, &g, u01, JUMPY_K, &new_f);
        bigint_signed_axby_shr_k(&f, u10, &g, u11, JUMPY_K, &new_g);
        f = new_f;
        g = new_g;

        // Apply matrix mod p to (u, v): m-trick generalized for ax + by.
        var new_u: BigInt;
        var new_v: BigInt;
        bigint_signed_axby_modp_halve_k(&u, u00, &v, u01, &p_const, JUMPY_K, &new_u);
        bigint_signed_axby_modp_halve_k(&u, u10, &v, u11, &p_const, JUMPY_K, &new_v);
        u = new_u;
        v = new_v;
    }

    // Defensive: if \`a\` was 0 (or didn't converge), return 0.
    if (!found) {
        var zero: BigInt;
        return zero;
    }

    // a^(-1) ≡ sign(f) · u (mod p). If f is negative, negate u mod p.
    var inv_native: BigInt = u;
    if (bigint_is_neg_2c(&f)) {
        var negated: BigInt;
        let _b = bigint_sub(&p_const, &u, &negated);
        inv_native = negated;
    }

    // Convert native → Montgomery: mont_product(inv_native, R^3).
    var r_cubed: BigInt = get_r_cubed();
    return montgomery_product(&inv_native, &r_cubed);
}

// Plain safegcd (1 divstep per iteration). Kept for A/B comparison
// against the jumpy \`fr_inv\` above. Not called by production.
fn fr_inv_plain(a: BigInt) -> BigInt {
    var f: BigInt = get_p();
    var g: BigInt = a;
    var v: BigInt;             // 0 (default-init)
    var r: BigInt;
    r.limbs[0] = 1u;           // 1
    var delta: i32 = 1;

    var p_const: BigInt = get_p();

    var found = false;
    for (var iter: u32 = 0u; iter < 750u; iter = iter + 1u) {
        if (bigint_is_zero(&g)) {
            found = true;
            break;
        }

        let g_low: u32 = g.limbs[0] & 1u;
        let take_swap: bool = (delta > 0) && (g_low == 1u);

        if (take_swap) {
            var diff: BigInt;
            bigint_sub_2c(&g, &f, &diff);
            bigint_arith_shr1(&diff);
            var saved_g: BigInt = g;
            f = saved_g;
            g = diff;
            delta = 1 - delta;

            var rv_diff: BigInt = fr_sub(&r, &v);
            bigint_halve_k_mod_p(&rv_diff, &p_const, 1u);
            v = r;
            r = rv_diff;
        } else if (g_low == 1u) {
            var sum: BigInt;
            bigint_add_2c(&g, &f, &sum);
            bigint_arith_shr1(&sum);
            g = sum;
            delta = delta + 1;

            var rv_sum: BigInt = fr_add(&r, &v);
            bigint_halve_k_mod_p(&rv_sum, &p_const, 1u);
            r = rv_sum;
        } else {
            bigint_arith_shr1(&g);
            delta = delta + 1;
            bigint_halve_k_mod_p(&r, &p_const, 1u);
        }
    }

    if (!found) {
        var zero: BigInt;
        return zero;
    }

    var inv_native: BigInt = v;
    if (bigint_is_neg_2c(&f)) {
        var negated: BigInt;
        let _b = bigint_sub(&p_const, &v, &negated);
        inv_native = negated;
    }

    var r_cubed: BigInt = get_r_cubed();
    return montgomery_product(&inv_native, &r_cubed);
}

// Legacy binary-extended-GCD fr_inv. Kept available for A/B comparison
// against the safegcd path above. Not called by the production kernel
// — the dispatcher picks \`fr_inv\` (safegcd). To swap back, rename
// \`fr_inv_bgcd\` here to \`fr_inv\` and rename the safegcd version above
// to something else.
//
// Two perf optimisations on top of the textbook formulation:
//
//   * CTZ-bulk halving (T1.b). The textbook "while u even: shr1" inner
//     loop iterates one bit at a time; instead we read the trailing-zero
//     count of u's low limb and shift by that many bits in one limb-pass.
//     For x1 we use the m-trick \`bigint_halve_k_mod_p\`: the unique
//     m ∈ [0, 2^k) with (x1 + m·p) ≡ 0 (mod 2^k) lets us perform k
//     halvings as one BigInt-add and one shr-by-k. Average ~2× speedup
//     on the inner halving block (random binary GCD has E[ctz] ≈ 2).
//
//   * Limb-bound tracking (T1.c). We keep \`top_u\`, \`top_v\` as loose
//     upper bounds on the highest non-zero limb of u and v. Both shrink
//     monotonically as the algorithm progresses; using the bounded
//     \`_top\` variants of shr1 / is_one / gte / sub halves the per-op
//     cost on average across the ~250 outer iterations it takes for
//     254-bit inputs to converge.
fn fr_inv_bgcd(a: BigInt) -> BigInt {
    var u: BigInt = a;
    var v: BigInt = get_p();

    var x1: BigInt;             // x1 = 1
    x1.limbs[0] = 1u;
    var x2: BigInt;             // x2 = 0  (default-initialized)

    var p_const: BigInt = get_p();

    // Loose upper bounds on the topmost non-zero limb of u and v. p
    // uses limb (NUM_WORDS - 1) (BN254: bit 254 fits in limb 19), and
    // a < p so u also fits there at start. Both shrink monotonically;
    // we tighten with \`bigint_recompute_top\` after every shift /
    // subtraction. x1 / x2 stay in [0, p) throughout, so they don't
    // benefit from limb-bound tracking.
    var top_u: u32 = NUM_WORDS - 1u;
    var top_v: u32 = NUM_WORDS - 1u;

    var inv_native: BigInt;
    var found = false;
    for (var iter: u32 = 0u; iter < 1024u; iter = iter + 1u) {
        if (bigint_is_one_top(&u, top_u)) {
            inv_native = x1;
            found = true;
            break;
        }
        if (bigint_is_one_top(&v, top_v)) {
            inv_native = x2;
            found = true;
            break;
        }

        // Halve u while it's even, applying matched halvings to x1 mod p
        // so the invariant A * x1 ≡ u (mod p) is maintained. The
        // \`bigint_ctz_lo_capped\` returns 1..WORD_SIZE-1 trailing zeros
        // of the low limb; if the low limb itself is zero (we've cleared
        // a full word of trailing zeros) it returns WORD_SIZE-1, so the
        // bulk shift always makes progress and we re-enter the loop to
        // strip more.
        loop {
            if (!bigint_is_even(&u)) { break; }
            let k = bigint_ctz_lo_capped(&u);
            bigint_shr_k_in_word_top(&u, k, top_u);
            top_u = bigint_recompute_top(&u, top_u);
            bigint_halve_k_mod_p(&x1, &p_const, k);
        }

        // Same for v / x2.
        loop {
            if (!bigint_is_even(&v)) { break; }
            let k = bigint_ctz_lo_capped(&v);
            bigint_shr_k_in_word_top(&v, k, top_v);
            top_v = bigint_recompute_top(&v, top_v);
            bigint_halve_k_mod_p(&x2, &p_const, k);
        }

        // Both u and v are now odd. Subtract the smaller from the
        // larger; mirror the subtraction on the x1/x2 coefficients
        // mod p (fr_sub returns canonical [0, p)). The cost-bounding
        // top is the larger of the two — at most one of u, v can be
        // > the other so iterating up to max(top_u, top_v) is tight.
        let top_uv: u32 = max(top_u, top_v);
        if (bigint_gte_top(&u, &v, top_uv)) {
            bigint_sub_top_inplace(&u, &v, top_uv);
            top_u = bigint_recompute_top(&u, top_u);
            x1 = fr_sub(&x1, &x2);
        } else {
            bigint_sub_top_inplace(&v, &u, top_uv);
            top_v = bigint_recompute_top(&v, top_v);
            x2 = fr_sub(&x2, &x1);
        }
    }

    // Defensive: if \`a\` was 0 the algorithm would not converge — return
    // 0 in that case (and any caller passing a zero delta is already
    // buggy upstream; the schedule kernel filters delta == 0).
    if (!found) {
        var zero: BigInt;
        return zero;
    }

    // inv_native = a^(-1) * R^(-1) mod p (in [0, p)).
    // Multiply by R^3 in Montgomery domain to land back in Montgomery
    // form: see derivation in the function header.
    var r_cubed: BigInt = get_r_cubed();
    return montgomery_product(&inv_native, &r_cubed);
}
`;

export const mont_pro_product = `const NUM_WORDS = {{ num_words }}u;
const WORD_SIZE = {{ word_size }}u;
const MASK = {{ mask }}u;
const TWO_POW_WORD_SIZE = {{ two_pow_word_size }}u;
const N0 = {{ n0 }}u;
// p^(-1) mod 2^WORD_SIZE. Used by \`bigint_halve_k_mod_p\` (the m-trick
// in fr_inv's CTZ-bulk halving): given x in [0, p), find m in [0, 2^k)
// such that x + m·p ≡ 0 (mod 2^k), then x' = (x + m·p) >> k. Solving
// for m: m ≡ -x · p^(-1) (mod 2^k). Since p is odd, p^(-1) mod 2^k
// exists and equals (p^(-1) mod 2^WORD_SIZE) & ((1<<k)-1) for any k
// ≤ WORD_SIZE.
const P_INV_MOD_2W = {{ p_inv_mod_2w }}u;

fn get_p() -> BigInt {
    var p: BigInt;
{{{ p_limbs }}}
    return p;
}

// An optimised variant of the Montgomery product algorithm from
// https://github.com/mitschabaude/montgomery#13-x-30-bit-multiplication
fn montgomery_product(x: ptr<function, BigInt>, y: ptr<function, BigInt>) -> BigInt {
    var s: BigInt;
    var p = get_p();

    for (var i = 0u; i < NUM_WORDS; i ++) {
        var t = s.limbs[0] + (*x).limbs[i] * (*y).limbs[0];

        var tprime = t & MASK;

        var qi = (N0 * tprime) & MASK;

        var c = (t + qi * p.limbs[0]) >> WORD_SIZE;

        s.limbs[0] = s.limbs[1] + (*x).limbs[i] * (*y).limbs[1] + qi * p.limbs[1] + c;

        // Since nSafe = 32 when NUM_WORDS = 20, we can perform the following
        // iterations without performing a carry.
        for (var j = 2u; j < NUM_WORDS; j ++) {
            s.limbs[j - 1u] = s.limbs[j] + (*x).limbs[i] * (*y).limbs[j] + qi * p.limbs[j];
        }

        s.limbs[NUM_WORDS - 2u] = (*x).limbs[i] * (*y).limbs[NUM_WORDS - 1u] + qi * p.limbs[NUM_WORDS - 1u];
    }

    // To paraphrase mitschabaude: a last round of carries to ensure that each
    // limb is at most WORD_SIZE bits
    var c = 0u;
    for (var i = 0u; i < NUM_WORDS; i ++) {
        var v = s.limbs[i] + c;
        c = v >> WORD_SIZE;
        s.limbs[i] = v & MASK;
    }

    return conditional_reduce(&s, &p);
}

fn conditional_reduce(x: ptr<function, BigInt>, y: ptr<function, BigInt>) -> BigInt {
    // Reduce when x >= y, not just x > y. The equality case matters: if x is
    // a limb-wise copy of p (value-0 mod p but non-canonical), is_zero() would
    // return false downstream, and that breaks identity checks in the EC
    // shaders. Reducing on == ensures the output is always canonical in
    // [0, p).
    var x_gt_y = bigint_gt(x, y);
    var x_eq_y = bigint_eq(x, y);

    if (x_gt_y == 1u || x_eq_y) {
        var res: BigInt;
        bigint_sub(x, y, &res);
        return res;
    }

    return *x;
}
`;

export const structs = `struct Point {
  x: BigInt,
  y: BigInt,
  z: BigInt
}

struct BigInt {
    limbs: array<u32, {{ num_words }}>
}
`;
